export { createRetryPolicy } from "./net/retry.js";
export { parseHeaders } from "./net/headers.js";
export { createRateLimiter } from "./net/rate-limiter.js";

// Sliding-window rate limiter
// Allows at most `limit` acquisitions within any trailing window of `windowMs` milliseconds.
export function createRateLimiter(limit, windowMs) {
  if (typeof limit !== 'number' || limit <= 0 || !Number.isFinite(limit)) {
    throw new TypeError('limit must be a positive finite number');
  }
  if (typeof windowMs !== 'number' || windowMs <= 0 || !Number.isFinite(windowMs)) {
    throw new TypeError('windowMs must be a positive finite number');
  }

  const timestamps = [];

  return {
    tryAcquire(nowMs) {
      if (typeof nowMs !== 'number' || !Number.isFinite(nowMs)) {
        throw new TypeError('nowMs must be a finite number');
      }

      // Remove timestamps older than the window
      const windowStart = nowMs - windowMs;
      while (timestamps.length && timestamps[0] < windowStart) {
        timestamps.shift();
      }

      if (timestamps.length < limit) {
        timestamps.push(nowMs);
        return true;
      }

      return false;
    }
  };
}

