// Test 1: Basic functionality
console.log('Test 1: Basic functionality');
const limiter = createRateLimiter(2, 1000); // 2 requests per second
let now = 0;

// First two should pass
console.log(`t=${now}:`, limiter.tryAcquire(now)); // true
now += 100;
console.log(`t=${now}:`, limiter.tryAcquire(now)); // true
// Third should fail
console.log(`t=${now}:`, limiter.tryAcquire(now)); // false

// Advance time so that first request falls out of window
now = 1100; // 1100 ms - first request at 0 is now out of window (1000 ms window)
console.log(`t=${now}:`, limiter.tryAcquire(now)); // true (because only one request in window: at 100 ms)
now += 100;
console.log(`t=${now}:`, limiter.tryAcquire(now)); // true (requests at 100 and 1200? Wait, we are at 1200 now? Let's recalc)

