let t3 = 0;
console.log(`t=${t3}:`, limiter3c.tryAcquire(t3)); // true (req at 0)
t3 += 500; // t3=500
console.log(`t=${t3}:`, limiter3c.tryAcquire(t3)); // true (req at 500) -> total 2
t3 += 500; // t3=1000
console.log(`t=${t3}:`, limiter3c.tryAcquire(t3)); // ? At t=1000, window start=0. We have requests at 0 and 500 (both >=0) -> count=2 -> should be false.
console.log(`t=${t3}:`, limiter3c.tryAcquire(t3)); // false
